  font-family: "Orbitron";
  src: url("./vendor/fonts/orbitron-700.ttf") format("truetype");
  font-weight: 700;
  font-display: swap;
}
@font-face {
  font-family: "Orbitron";
  src: url("./vendor/fonts/orbitron-900.ttf") format("truetype");
  font-weight: 900;
  font-display: swap;
}
@font-face {
  font-family: "Rajdhani";
  src: url("./vendor/fonts/rajdhani-500.ttf") format("truetype");
