import * as THREE from "three";
import {
  clamp, fbm, lerp, makeRadialCanvas, mulberry32, randRange,
  smoothstep, TAU,
} from "./util.js";

export const ARENA = { halfX: 46, halfZ: 36 };

export const LAVA_POOLS = [
  { cx: -25, cz: 4, rx: 11.5, rz: 5.2, rot: 0.35, seed: 12 },
  { cx: 24, cz: -7, rx: 9.5, rz: 6.4, rot: -0.45, seed: 43 },
  { cx: -18, cz: 27, rx: 8.5, rz: 3.8, rot: -0.2, seed: 71 },
  { cx: 24, cz: 25, rx: 6.8, rz: 4.6, rot: 0.6, seed: 97 },
  { cx: 37, cz: 10, rx: 4.6, rz: 3.1, rot: 0.1, seed: 133 },
];

export function terrainHeight(x, z) {
  const ax = Math.abs(x);
  const az = Math.abs(z);
  const edge = smoothstep(0, 1, Math.max((ax - 45) / 22, (az - 34) / 18));
  const broad = (fbm(x * 0.075 + 13.2, z * 0.075 - 7.1, 4) - 0.5) * 1.15;
  const detail = (fbm(x * 0.28 - 4.4, z * 0.28 + 9.5, 3) - 0.5) * 0.22;
  const rim = Math.pow(edge, 1.55) * 9.5;
  return (broad + detail) * (0.16 + edge * 1.8) + rim;
}

function makeGround(scene) {
  const geo = new THREE.PlaneGeometry(170, 140, 170, 140);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const cA = new THREE.Color(0x241d22);
  const cB = new THREE.Color(0x5c4c43);
  const cC = new THREE.Color(0x7a5b45);
  const cDark = new THREE.Color(0x171216);
  const tmp = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    const z = pos.getZ(i);
    const h = terrainHeight(x, z);
    pos.setY(i, h);
    const n = fbm(x * 0.13 + 4.2, z * 0.13 - 2.4, 4);
    const n2 = fbm(x * 0.55, z * 0.55, 2);
    tmp.copy(cA).lerp(cB, smoothstep(0.28, 0.78, n)).lerp(cC, smoothstep(0.62, 0.92, n2) * 0.32);
    tmp.lerp(cDark, smoothstep(1.4, 7.0, h) * 0.75);
    const shade = 0.8 + n2 * 0.3;
    colors[i * 3] = tmp.r * shade;
    colors[i * 3 + 1] = tmp.g * shade;
    colors[i * 3 + 2] = tmp.b * shade;
  }
  geo.setAttribute("color", new THREE.BufferAttribute(colors, 3));
  geo.computeVertexNormals();
  const mat = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.94,
    metalness: 0.06,
    flatShading: true,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.receiveShadow = true;
  mesh.castShadow = false;
  scene.add(mesh);

  // Engraved arena circle.
  const ringMat = new THREE.MeshBasicMaterial({
    color: 0xff6b21, transparent: true, opacity: 0.32,
    blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
  });
  const ring = new THREE.Mesh(new THREE.RingGeometry(12.1, 12.28, 128), ringMat);
  ring.rotation.x = -Math.PI / 2;
  ring.position.y = 0.24;
  scene.add(ring);
  const inner = new THREE.Mesh(new THREE.RingGeometry(11.55, 11.68, 128), ringMat.clone());
  inner.material.opacity = 0.12;
  inner.rotation.x = -Math.PI / 2;
  inner.position.y = 0.24;
  scene.add(inner);

  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU;
    const tick = new THREE.Mesh(new THREE.PlaneGeometry(0.14, 1.8), ringMat.clone());
    tick.material.opacity = i % 2 ? 0.18 : 0.33;
    tick.rotation.x = -Math.PI / 2;
    tick.rotation.z = -a;
    tick.position.set(Math.cos(a) * 12.9, 0.24, Math.sin(a) * 12.9);
    scene.add(tick);
  }
  return mesh;
}

function createBoulderGeometries() {
  const rng = mulberry32(9137);
  const list = [];
  for (let v = 0; v < 7; v++) {
    const geo = new THREE.IcosahedronGeometry(1, v < 4 ? 1 : 2);
    const pos = geo.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
      const n = fbm(x * 2.2 + v * 8.3, z * 2.2 - v * 4.1 + y * 1.7, 3);
      const scale = 0.72 + n * 0.62;
      pos.setXYZ(i, x * scale, y * (scale * 0.92), z * scale);
    }
    geo.computeVertexNormals();
    list.push(geo);
  }
  return list;
}

function makeRock(scene, geos, rng, x, z, sx, sy, sz, colliderList, tint) {
  const geo = geos[Math.floor(rng() * geos.length)];
  const grey = 0.24 + rng() * 0.2;
  const color = new THREE.Color().setHSL(0.055 + rng() * 0.035, 0.12 + rng() * 0.12, grey);
  if (tint) color.lerp(new THREE.Color(tint), 0.28);
  const mat = new THREE.MeshStandardMaterial({
    color, roughness: 0.9, metalness: 0.08, flatShading: true,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(x, terrainHeight(x, z) + sy * 0.34 - 0.35, z);
  mesh.rotation.set(rng() * 0.4 - 0.2, rng() * TAU, rng() * 0.3 - 0.15);
  mesh.scale.set(sx, sy, sz);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  scene.add(mesh);
  if (colliderList && sx > 1.1) {
    colliderList.push({ x, z, r: Math.min(sx, sz) * 0.68, h: sy });
  }
  return mesh;
}

function buildRockField(scene) {
  const rng = mulberry32(2287);
  const geos = createBoulderGeometries();
  const colliders = [];

  // Big rocks hugging each lava pool.
  for (const pool of LAVA_POOLS) {
    const count = Math.round((pool.rx + pool.rz) * 0.75);
    for (let i = 0; i < count; i++) {
      const a = (i / count) * TAU + rng() * 0.4;
      const off = 1.16 + rng() * 0.38;
      const x = pool.cx + Math.cos(a) * pool.rx * off;
      const z = pool.cz + Math.sin(a) * pool.rz * off;
      if (Math.abs(x) > 47 || Math.abs(z) > 37) continue;
      if (Math.hypot(x, z - 14) < 6 || Math.hypot(x, z + 14) < 6) continue;
      const s = 0.7 + rng() * 1.5;
      makeRock(scene, geos, rng, x, z, s * (0.9 + rng() * 0.5), s * (0.65 + rng() * 0.5), s, colliders, 0x5b3628);
    }
  }

  // Scattered arena boulders, kept out of the central duel lane.
  let placed = 0;
  let guard = 0;
  while (placed < 22 && guard++ < 300) {
    const x = (rng() * 2 - 1) * 43;
    const z = (rng() * 2 - 1) * 33;
    const central = Math.abs(x) < 10 && Math.abs(z) < 24;
    const spawn = Math.hypot(x, z - 14) < 7 || Math.hypot(x, z + 14) < 7;
    if (central || spawn) continue;
    if (LAVA_POOLS.some((p) => ((x - p.cx) / (p.rx * 1.5)) ** 2 + ((z - p.cz) / (p.rz * 1.7)) ** 2 < 1)) continue;
    const s = 0.55 + rng() * 1.35;
    makeRock(scene, geos, rng, x, z, s * (0.85 + rng() * 0.55), s * (0.7 + rng() * 0.55), s, colliders);
    placed++;
  }

  // Boundary cliffs.
  for (let side = -1; side <= 1; side += 2) {
    for (let z = -48; z <= 48; z += 6.2) {
      const x = side * (52 + rng() * 5);
      const s = 5.2 + rng() * 4.6;
      makeRock(scene, geos, rng, x, z + rng() * 3, s, (s * 1.15) + rng() * 4, s * 0.9, null, 0x24191d);
    }
    for (let x = -54; x <= 54; x += 6.4) {
      const z = side * (41 + rng() * 5);
      const s = 4.6 + rng() * 4.4;
      makeRock(scene, geos, rng, x + rng() * 3, z, s, (s * 1.1) + rng() * 3.4, s * 0.9, null, 0x24191d);
    }
  }

  // Distant mesas and spires.
  const mesaMat = new THREE.MeshStandardMaterial({ color: 0x1b1217, roughness: 0.98, metalness: 0.03, flatShading: true });
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * TAU + rng() * 0.2;
    const dist = 96 + rng() * 65;
    const x = Math.cos(a) * dist;
    const z = Math.sin(a) * dist;
    const h = 18 + rng() * 34;
    const geo = new THREE.CylinderGeometry(4 + rng() * 8, 11 + rng() * 13, h, 6, 2);
    const mesh = new THREE.Mesh(geo, mesaMat);
    mesh.position.set(x, h * 0.4 - 5, z);
    mesh.rotation.y = rng() * TAU;
    scene.add(mesh);
  }

  return colliders;
}

function lavaShape(pool) {
  const shape = new THREE.Shape();
  const points = 52;
  for (let i = 0; i <= points; i++) {
    const a = (i / points) * TAU;
    const wobble = 1
      + Math.sin(a * 3 + pool.seed) * 0.11
      + Math.sin(a * 5 - pool.seed * 0.7) * 0.07
      + Math.sin(a * 7 + pool.seed * 1.3) * 0.04;
    const x = Math.cos(a) * pool.rx * wobble;
    const y = Math.sin(a) * pool.rz * wobble;
    if (i === 0) shape.moveTo(x, y); else shape.lineTo(x, y);
  }
  return new THREE.ShapeGeometry(shape, 4);
}

const LAVA_VERT = /* glsl */`
  varying vec3 vWorld;
  varying vec2 vUv;
  void main() {
    vUv = uv;
    vec4 world = modelMatrix * vec4(position, 1.0);
    vWorld = world.xyz;
    gl_Position = projectionMatrix * viewMatrix * world;
  }
`;

const LAVA_FRAG = /* glsl */`
  uniform float uTime;
  uniform float uSeed;
  varying vec3 vWorld;
  varying vec2 vUv;

  float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
  }
  float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
  }
  float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
      v += a * noise(p);
      p = p * 2.07 + vec2(3.1, 1.7);
      a *= 0.5;
    }
    return v;
  }

  void main() {
    vec2 p = vWorld.xz * 0.24 + uSeed;
    float t = uTime;
    float n = fbm(p * 1.4 + vec2(t * 0.10, -t * 0.07));
    float n2 = fbm(p * 3.2 - vec2(t * 0.16, t * 0.11) + 11.4);
    float veins = smoothstep(0.38, 0.72, n2 + n * 0.35);
    float hot = smoothstep(0.28, 0.82, n);
    vec3 deep = vec3(0.48, 0.045, 0.006);
    vec3 mid = vec3(1.35, 0.24, 0.012);
    vec3 hotc = vec3(1.9, 0.98, 0.32);
    vec3 col = mix(deep, mid, smoothstep(0.16, 0.7, n));
    col = mix(col, hotc, pow(veins, 1.7) * 0.95);
    col += vec3(1.2, 0.2, 0.0) * hot * 0.32;
    float pulse = 0.91 + 0.09 * sin(t * 1.5 + uSeed * 3.1 + n * 5.0);
    col *= pulse;
    gl_FragColor = vec4(col, 1.0);
  }
`;

function buildLava(scene, glowTexture) {
  const bubbles = [];
  const lights = [];
  const glowSprites = [];
  const bubbleGeo = new THREE.IcosahedronGeometry(1, 1);
  const bubbleMat = new THREE.MeshStandardMaterial({
    color: 0xff5a10, emissive: 0xff4d0a, emissiveIntensity: 3.2,
    roughness: 0.25, metalness: 0.1,
  });

  for (const pool of LAVA_POOLS) {
    const geo = lavaShape(pool);
    const mat = new THREE.ShaderMaterial({
      uniforms: { uTime: { value: 0 }, uSeed: { value: pool.seed * 0.41 } },
      vertexShader: LAVA_VERT,
      fragmentShader: LAVA_FRAG,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.rotation.z = pool.rot;
    mesh.position.set(pool.cx, 0.19, pool.cz);
    scene.add(mesh);
    pool.material = mat;

    // Wide ambient glow bed.
    const glowPlane = new THREE.Mesh(
      new THREE.PlaneGeometry(pool.rx * 3.3, pool.rz * 3.1),
      new THREE.MeshBasicMaterial({
        map: glowTexture, color: 0xff5a18, transparent: true, opacity: 0.33,
        blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
      }),
    );
    glowPlane.rotation.x = -Math.PI / 2;
    glowPlane.rotation.z = pool.rot;
    glowPlane.position.set(pool.cx, 0.05, pool.cz);
    scene.add(glowPlane);
    glowSprites.push(glowPlane);

    const light = new THREE.PointLight(0xff5d16, 85, 30, 2);
    light.position.set(pool.cx, 2.2, pool.cz);
    scene.add(light);
    lights.push({ light, base: 85, seed: pool.seed });

    const count = Math.round(8 + (pool.rx + pool.rz) * 0.75);
    for (let i = 0; i < count; i++) {
      const a = Math.random() * TAU;
      const r = Math.sqrt(Math.random()) * 0.72;
      bubbles.push({
        x: pool.cx + Math.cos(a) * pool.rx * r,
        z: pool.cz + Math.sin(a) * pool.rz * r,
        phase: Math.random(), speed: 0.16 + Math.random() * 0.24,
        size: 0.055 + Math.random() * 0.12,
      });
    }
  }

  const inst = new THREE.InstancedMesh(bubbleGeo, bubbleMat, bubbles.length);
  inst.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  inst.frustumCulled = false;
  scene.add(inst);
  const dummy = new THREE.Object3D();

  return {
    lights, glowSprites, inst, bubbles, dummy,
    update(time) {
      for (const pool of LAVA_POOLS) pool.material.uniforms.uTime.value = time;
      for (const { light, base, seed } of lights) {
        light.intensity = base * (0.82 + Math.sin(time * 2.1 + seed) * 0.09 + Math.sin(time * 5.3 + seed * 2.0) * 0.05);
      }
      for (const g of glowSprites) {
        g.material.opacity = 0.29 + Math.sin(time * 1.4 + g.position.x) * 0.035;
      }
      for (let i = 0; i < bubbles.length; i++) {
        const b = bubbles[i];
        const t = (time * b.speed + b.phase) % 1;
        const scale = b.size * Math.sin(Math.PI * Math.min(1, t * 1.15)) * (0.7 + t * 0.8);
        const y = 0.18 + t * 0.18;
        dummy.position.set(b.x, y, b.z);
        dummy.scale.setScalar(Math.max(0.001, scale));
        dummy.rotation.set(t * 3, t * 4, 0);
        dummy.updateMatrix();
        inst.setMatrixAt(i, dummy.matrix);
      }
      inst.instanceMatrix.needsUpdate = true;
    },
  };
}

function makeCracks(scene) {
  const rng = mulberry32(5571);
  const mat = new THREE.MeshBasicMaterial({
    color: 0xff5c14, transparent: true, opacity: 0.72,
    blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
  });
  for (let i = 0; i < 9; i++) {
    const pool = LAVA_POOLS[i % LAVA_POOLS.length];
    const a = rng() * TAU;
    const startX = pool.cx + Math.cos(a) * pool.rx * 1.08;
    const startZ = pool.cz + Math.sin(a) * pool.rz * 1.08;
    const dir = a + (rng() - 0.5) * 0.8;
    const pts = [];
    let x = startX, z = startZ;
    for (let j = 0; j < 5; j++) {
      x += Math.cos(dir + (rng() - 0.5) * 0.9) * (1.4 + rng() * 2.2);
      z += Math.sin(dir + (rng() - 0.5) * 0.9) * (1.4 + rng() * 2.2);
      pts.push(new THREE.Vector3(x, terrainHeight(x, z) + 0.06, z));
    }
    const curve = new THREE.CatmullRomCurve3(pts);
    const geo = new THREE.TubeGeometry(curve, 14, 0.045 + rng() * 0.035, 4, false);
    scene.add(new THREE.Mesh(geo, mat));
  }
}

function makeSky(scene) {
  const geo = new THREE.SphereGeometry(420, 32, 20);
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {},
    vertexShader: /* glsl */`
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */`
      varying vec3 vDir;
      void main() {
        float h = vDir.y;
        vec3 top = vec3(0.022, 0.018, 0.045);
        vec3 mid = vec3(0.115, 0.045, 0.075);
        vec3 low = vec3(0.62, 0.19, 0.075);
        vec3 col = mix(low, mid, smoothstep(-0.06, 0.22, h));
        col = mix(col, top, smoothstep(0.2, 0.85, h));
        vec3 sunDir = normalize(vec3(-0.35, 0.14, -0.62));
        float sun = pow(max(dot(normalize(vDir), sunDir), 0.0), 26.0);
        col += vec3(1.4, 0.48, 0.14) * sun * 0.75;
        float haze = pow(max(0.0, 1.0 - abs(h) * 4.0), 3.0);
        col += vec3(0.32, 0.075, 0.022) * haze * 0.45;
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });
  const sky = new THREE.Mesh(geo, mat);
  sky.frustumCulled = false;
  scene.add(sky);
  return sky;
}

export function createWorld(scene) {
  scene.fog = new THREE.Fog(0x180d11, 58, 190);
  const glowCanvas = makeRadialCanvas("rgba(255,186,102,0.95)", "rgba(255,60,4,0)");
  const glowTexture = new THREE.CanvasTexture(glowCanvas);
  glowTexture.colorSpace = THREE.SRGBColorSpace;

  makeSky(scene);
  makeGround(scene);
  const colliders = buildRockField(scene);
  const lava = buildLava(scene, glowTexture);
  makeCracks(scene);

  const hemi = new THREE.HemisphereLight(0x7c6a9a, 0x3d1a0c, 1.15);
  scene.add(hemi);

  const sun = new THREE.DirectionalLight(0xffc79a, 2.45);
  sun.position.set(-32, 52, 28);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.left = -62;
  sun.shadow.camera.right = 62;
  sun.shadow.camera.top = 58;
  sun.shadow.camera.bottom = -58;
  sun.shadow.camera.near = 2;
  sun.shadow.camera.far = 140;
  sun.shadow.bias = -0.0009;
  sun.shadow.normalBias = 0.035;
  sun.target.position.set(0, 0, 0);
  scene.add(sun, sun.target);

  const rim = new THREE.DirectionalLight(0x5a86ff, 0.75);
  rim.position.set(30, 24, -46);
  scene.add(rim);

  // Floating embers.
  const emberCount = 260;
  const emberPos = new Float32Array(emberCount * 3);
  const emberData = [];
  const rng = mulberry32(881);
  for (let i = 0; i < emberCount; i++) {
    const x = (rng() * 2 - 1) * 52;
    const z = (rng() * 2 - 1) * 40;
    const y = 0.4 + rng() * 11;
    emberPos.set([x, y, z], i * 3);
    emberData.push({ speed: 0.35 + rng() * 0.9, phase: rng() * TAU, drift: 0.2 + rng() * 0.4 });
  }
  const emberGeo = new THREE.BufferGeometry();
  emberGeo.setAttribute("position", new THREE.BufferAttribute(emberPos, 3));
  const emberMat = new THREE.PointsMaterial({
    map: glowTexture, color: 0xff8a3c, size: 0.17, transparent: true, opacity: 0.9,
    blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true,
  });
  const embers = new THREE.Points(emberGeo, emberMat);
  scene.add(embers);

  const clock = { t: 0 };
  return {
    colliders,
    lava,
    sun,
    update(dt) {
      clock.t += dt;
      const t = clock.t;
      lava.update(t);
      const arr = emberGeo.attributes.position.array;
      for (let i = 0; i < emberCount; i++) {
        const d = emberData[i];
        arr[i * 3 + 1] += d.speed * dt;
        arr[i * 3] += Math.sin(t * 0.6 + d.phase) * d.drift * dt;
        arr[i * 3 + 2] += Math.cos(t * 0.5 + d.phase) * d.drift * dt;
        if (arr[i * 3 + 1] > 13) {
          arr[i * 3 + 1] = 0.25;
          arr[i * 3] = (Math.random() * 2 - 1) * 52;
          arr[i * 3 + 2] = (Math.random() * 2 - 1) * 40;
        }
      }
      emberGeo.attributes.position.needsUpdate = true;
      embers.material.opacity = 0.72 + Math.sin(t * 2.3) * 0.06;
    },
  };
}

import * as THREE from "three";
import { damp, dampAngle, lerp, smoothstep } from "./util.js";

const OUTLINE = 0x0b0b10;

function box(w, h, d, mat, x = 0, y = 0, z = 0) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  mesh.position.set(x, y, z);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function cyl(rt, rb, h, seg, mat, x = 0, y = 0, z = 0) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, seg), mat);
  mesh.position.set(x, y, z);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function sphere(r, mat, x = 0, y = 0, z = 0, scale) {
  const mesh = new THREE.Mesh(new THREE.IcosahedronGeometry(r, 2), mat);
  mesh.position.set(x, y, z);
  if (scale) mesh.scale.copy(scale);
  mesh.castShadow = true;
  return mesh;
}

function outline(mesh, opacity = 0.42) {
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(mesh.geometry, 34),
    new THREE.LineBasicMaterial({ color: OUTLINE, transparent: true, opacity }),
  );
  edges.raycast = () => {};
  mesh.add(edges);
  return mesh;
}

export function createRobot(kind = "player") {
  const isPlayer = kind === "player";
  const palette = isPlayer
    ? { armor: 0xaebccd, secondary: 0x323a4a, accent: 0xff7a1f, visor: 0x7df7ff, metal: 0xcfd8e4 }
    : { armor: 0x763139, secondary: 0x26191f, accent: 0xff341d, visor: 0xff5533, metal: 0xa4595b };

  const matArmor = new THREE.MeshStandardMaterial({ color: palette.armor, metalness: 0.78, roughness: 0.31 });
  const matMetal = new THREE.MeshStandardMaterial({ color: palette.metal, metalness: 0.9, roughness: 0.22 });
  const matSecondary = new THREE.MeshStandardMaterial({ color: palette.secondary, metalness: 0.72, roughness: 0.42 });
  const matAccent = new THREE.MeshStandardMaterial({
    color: palette.accent, emissive: palette.accent, emissiveIntensity: 1.65,
    metalness: 0.4, roughness: 0.35,
  });
  const matVisor = new THREE.MeshBasicMaterial({ color: palette.visor, toneMapped: false });
  const matDark = new THREE.MeshStandardMaterial({ color: 0x101116, metalness: 0.6, roughness: 0.55 });
  const mats = [matArmor, matMetal, matSecondary, matAccent, matVisor, matDark];
  for (const m of mats) m.userData.baseEmissive = m.emissive ? m.emissive.clone() : null;

  const root = new THREE.Group();
  const body = new THREE.Group();
  root.add(body);

  // Pelvis and waist.
  const pelvis = outline(box(0.68, 0.26, 0.44, matSecondary, 0, 1.02, 0), 0.5);
  body.add(pelvis);
  body.add(box(0.5, 0.18, 0.36, matDark, 0, 1.18, 0));

  // Torso.
  const torso = new THREE.Group();
  torso.position.y = 1.36;
  body.add(torso);

  const chest = outline(box(0.98, 0.78, 0.58, matArmor, 0, 0.34, 0), 0.55);
  torso.add(chest);
  torso.add(box(0.54, 0.3, 0.1, matAccent, 0, 0.38, 0.33));
  const core = sphere(0.1, matVisor, 0, 0.34, 0.36);
  torso.add(core);
  torso.add(box(0.7, 0.12, 0.5, matSecondary, 0, 0.69, 0));
  torso.add(box(0.84, 0.18, 0.5, matMetal, 0, 0.02, 0));
  torso.add(box(0.32, 0.12, 0.06, matDark, -0.24, 0.16, 0.31));
  torso.add(box(0.32, 0.12, 0.06, matDark, 0.24, 0.16, 0.31));

  // Head.
  const head = new THREE.Group();
  head.position.y = 0.86;
  torso.add(head);
  const neck = cyl(0.12, 0.14, 0.16, 8, matDark, 0, -0.06, 0);
  head.add(neck);
  const skull = outline(box(0.5, 0.44, 0.48, matArmor, 0, 0.2, 0), 0.6);
  head.add(skull);
  head.add(box(0.42, 0.09, 0.06, matVisor, 0, 0.23, 0.26));
  head.add(box(0.36, 0.08, 0.05, matDark, 0, 0.08, 0.25));
  head.add(box(0.12, 0.06, 0.06, matAccent, 0, 0.33, 0.26));
  head.add(box(0.07, 0.26, 0.07, matMetal, 0.2, 0.5, -0.02));
  head.add(sphere(0.04, matAccent, 0.2, 0.64, -0.02));
  head.add(box(0.08, 0.1, 0.24, matSecondary, -0.28, 0.2, 0));
  head.add(box(0.08, 0.1, 0.24, matSecondary, 0.28, 0.2, 0));

  // Back thrusters.
  for (const sx of [-0.23, 0.23]) {
    const thruster = cyl(0.1, 0.13, 0.42, 8, matMetal, sx, 0.35, -0.34);
    thruster.rotation.x = 0.06;
    torso.add(thruster);
    torso.add(cyl(0.075, 0.075, 0.08, 8, matAccent, sx, 0.13, -0.34));
  }

  // Shoulders and arms.
  function makeArm(side) {
    const arm = new THREE.Group();
    arm.position.set(side * 0.68, 0.52, 0);
    const pauldron = sphere(0.28, matArmor, 0, 0.05, 0, new THREE.Vector3(1.05, 0.8, 1.1));
    outline(pauldron, 0.55);
    arm.add(pauldron);
    arm.add(box(0.2, 0.44, 0.22, matSecondary, 0, -0.32, 0));
    arm.add(sphere(0.105, matMetal, 0, -0.58, 0));
    arm.add(box(0.17, 0.4, 0.18, matArmor, 0, -0.81, 0));
    arm.add(box(0.2, 0.16, 0.23, matDark, 0, -1.05, 0));
    arm.add(box(0.24, 0.07, 0.28, matAccent, 0, -0.61, 0.02));
    return arm;
  }

  const armL = makeArm(-1);
  const armR = makeArm(1);
  torso.add(armL, armR);

  // Sword in the left hand.
  const sword = new THREE.Group();
  sword.position.set(0, -1.12, 0.06);
  armL.add(sword);
  const grip = cyl(0.045, 0.05, 0.26, 8, matDark, 0, -0.1, 0);
  sword.add(grip);
  sword.add(box(0.3, 0.06, 0.1, matMetal, 0, -0.23, 0));
  const bladeMat = new THREE.MeshStandardMaterial({
    color: 0xcffaff, emissive: palette.visor, emissiveIntensity: 1.7,
    metalness: 0.9, roughness: 0.16,
  });
  const blade = new THREE.Mesh(new THREE.BoxGeometry(0.075, 1.42, 0.17), bladeMat);
  blade.position.set(0, -0.96, 0);
  blade.castShadow = true;
  sword.add(blade);
  const tip = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.3, 4), bladeMat);
  tip.position.set(0, -1.81, 0);
  tip.rotation.z = Math.PI;
  tip.rotation.y = Math.PI / 4;
  sword.add(tip);
  const guard = box(0.14, 0.08, 0.16, matAccent, 0, -0.23, 0);
  sword.add(guard);
  sword.rotation.x = -0.35;

  // Shoulder-mounted bazooka.
  const bazooka = new THREE.Group();
  bazooka.position.set(0.5, 0.62, 0.02);
  torso.add(bazooka);
  const tube = cyl(0.18, 0.2, 1.48, 12, matArmor, 0, 0, 0.3);
  tube.rotation.x = Math.PI / 2;
  bazooka.add(tube);
  for (const z of [-0.18, 0.18, 0.58]) {
    const band = cyl(0.215, 0.215, 0.07, 12, matSecondary, 0, 0, z + 0.3);
    band.rotation.x = Math.PI / 2;
    bazooka.add(band);
  }
  const muzzleRing = cyl(0.21, 0.21, 0.12, 12, matDark, 0, 0, 1.06);
  muzzleRing.rotation.x = Math.PI / 2;
  bazooka.add(muzzleRing);
  const rear = cyl(0.17, 0.21, 0.28, 12, matSecondary, 0, 0, -0.52);
  rear.rotation.x = Math.PI / 2;
  bazooka.add(rear);
  bazooka.add(box(0.09, 0.22, 0.34, matAccent, 0, 0.18, 0.36));
  bazooka.add(box(0.13, 0.08, 0.42, matDark, -0.12, 0.12, 0.34));
  const muzzle = new THREE.Object3D();
  muzzle.position.set(0, 0, 1.16);
  bazooka.add(muzzle);

  // Legs.
  function makeLeg(side) {
    const leg = new THREE.Group();
    leg.position.set(side * 0.3, 1.02, 0);
    leg.add(box(0.3, 0.46, 0.32, matSecondary, 0, -0.24, 0));
    leg.add(sphere(0.12, matMetal, 0, -0.5, 0));
    const shin = box(0.25, 0.44, 0.28, matArmor, 0, -0.73, 0);
    leg.add(shin);
    leg.add(box(0.27, 0.07, 0.3, matAccent, 0, -0.56, 0.01));
    leg.add(box(0.32, 0.16, 0.5, matDark, 0, -0.98, 0.09));
    leg.add(box(0.24, 0.05, 0.1, matMetal, 0, -0.94, 0.36));
    return leg;
  }
  const legL = makeLeg(-1);
  const legR = makeLeg(1);
  body.add(legL, legR);

  // Chest emblem.
  const emblem = new THREE.Mesh(new THREE.RingGeometry(0.18, 0.23, 20), matAccent);
  emblem.position.set(0.52, 0.35, 0.305);
  torso.add(emblem);

  const robot = {
    kind,
    root,
    body,
    torso,
    head,
    armL,
    armR,
    legL,
    legR,
    sword,
    bazooka,
    muzzle,
    bladeMat,
    mats,
    walkPhase: 0,
    hitFlash: 0,
    deadT: 0,
    baseBodyY: 0,
  };
  root.userData.robot = robot;
  return robot;
}

export function setRobotFlash(robot, amount = 0.9) {
  robot.hitFlash = amount;
}

export function getRobotForward(robot, out = new THREE.Vector3()) {
  return out.set(0, 0, 1).applyQuaternion(robot.root.quaternion);
}

export function getRobotChest(robot, out = new THREE.Vector3()) {
  out.set(0, 1.75, 0.1);
  return robot.root.localToWorld(out);
}

const _v = new THREE.Vector3();

export function animateRobot(robot, dt, state, time) {
  const { speed = 0, aimPitch = 0, swing = -1, recoil = 0, dead = false } = state;
  const moving = speed > 0.35;
  const intensity = Math.min(1, speed / 4.6);

  if (moving) robot.walkPhase += dt * (5.4 + speed * 1.55);
  const phase = robot.walkPhase;
  const amp = moving ? 0.58 * intensity : 0;
  const sin = Math.sin(phase);

  robot.legL.rotation.x = damp(robot.legL.rotation.x, sin * amp, 14, dt);
  robot.legR.rotation.x = damp(robot.legR.rotation.x, -sin * amp, 14, dt);
  robot.armR.rotation.x = damp(robot.armR.rotation.x, -sin * amp * 0.48 - 0.04, 12, dt);
  robot.armR.rotation.z = damp(robot.armR.rotation.z, 0.04, 8, dt);

  const bob = moving ? Math.abs(Math.sin(phase)) * 0.045 * intensity : Math.sin(time * 1.8) * 0.012;
  robot.body.position.y = damp(robot.body.position.y, bob, 12, dt);

  robot.torso.rotation.y = damp(robot.torso.rotation.y, 0, 8, dt);
  robot.head.rotation.y = damp(robot.head.rotation.y, Math.sin(time * 0.7) * 0.05, 2, dt);
  robot.head.rotation.x = damp(robot.head.rotation.x, -aimPitch * 0.15, 6, dt);

  const bazookaAim = -aimPitch * 0.62;
  robot.bazooka.rotation.x = damp(robot.bazooka.rotation.x, bazookaAim, 9, dt);
  robot.bazooka.position.z = damp(robot.bazooka.position.z, 0.02 - recoil * 0.19, 16, dt);

  // Left sword arm: idle sway, or a diagonal slash.
  if (swing >= 0 && swing <= 1) {
    const wind = smoothstep(0, 0.25, swing);
    const cut = smoothstep(0.2, 0.62, swing);
    const recover = smoothstep(0.62, 1, swing);
    const y = lerp(0.35, -0.05, wind) + (-1.3 + 0.05) * cut + (1.25) * recover;
    const x = lerp(-0.12, -0.9, wind) + 0.45 * cut + 0.45 * recover;
    const z = lerp(0.16, 0.55, cut) - 0.4 * recover;
    robot.armL.rotation.y = y;
    robot.armL.rotation.x = x;
    robot.armL.rotation.z = z;
    robot.sword.rotation.x = lerp(-0.35, -0.05, cut);
  } else {
    robot.armL.rotation.y = damp(robot.armL.rotation.y, 0.08, 8, dt);
    robot.armL.rotation.x = damp(robot.armL.rotation.x, -0.12 + Math.sin(time * 1.5) * 0.025, 6, dt);
    robot.armL.rotation.z = damp(robot.armL.rotation.z, 0.16, 6, dt);
    robot.sword.rotation.x = damp(robot.sword.rotation.x, -0.35, 6, dt);
  }

  if (dead) {
    robot.deadT = Math.min(1, robot.deadT + dt * 1.9);
    const t = robot.deadT;
    robot.root.rotation.z = lerp(0, -1.28, t * t);
    robot.body.position.y = lerp(robot.body.position.y, -0.62 * t, 0.15);
    robot.head.rotation.x = lerp(0, 0.4, t);
    robot.armL.rotation.x = lerp(robot.armL.rotation.x, -0.6, t * 0.3);
    robot.armR.rotation.x = lerp(robot.armR.rotation.x, 0.7, t * 0.3);
  } else {
    robot.deadT = 0;
    robot.root.rotation.z = damp(robot.root.rotation.z, 0, 6, dt);
  }

  // Hit flash.
  if (robot.hitFlash > 0) {
    robot.hitFlash = Math.max(0, robot.hitFlash - dt * 3.2);
    const f = robot.hitFlash;
    for (const m of robot.mats) {
      if (m.emissive) {
        m.emissive.setRGB(
          Math.min(1, (m.userData.baseEmissive?.r ?? 0) + f * 1.4),
          Math.min(1, (m.userData.baseEmissive?.g ?? 0) + f * 0.5),
          Math.min(1, (m.userData.baseEmissive?.b ?? 0) + f * 0.35),
        );
      }
    }
    robot.bladeMat.emissiveIntensity = 1.7 + f * 4;
  } else {
    for (const m of robot.mats) {
      if (m.emissive && m.userData.baseEmissive) m.emissive.copy(m.userData.baseEmissive);
    }
    robot.bladeMat.emissiveIntensity = 1.7;
  }
}

export function pointRobotAt(robot, worldPoint, dt, turnSpeed = 12) {
  _v.copy(worldPoint).sub(robot.root.position);
  const target = Math.atan2(_v.x, _v.z);
  robot.root.rotation.y = dampAngle(robot.root.rotation.y, target, turnSpeed, dt);
}

export function faceYaw(robot, yaw, dt, turnSpeed = 14) {
  robot.root.rotation.y = dampAngle(robot.root.rotation.y, yaw, turnSpeed, dt);
}

import * as THREE from "three";
import { makeRadialCanvas, makeRingCanvas } from "./util.js";

const MAX_PARTICLES = 900;

export function createEffects(scene) {
  const sparkCanvas = makeRadialCanvas("rgba(255,255,255,1)", "rgba(255,255,255,0)");
  const sparkTexture = new THREE.CanvasTexture(sparkCanvas);
  sparkTexture.colorSpace = THREE.SRGBColorSpace;
  const ringTexture = new THREE.CanvasTexture(makeRingCanvas());
  ringTexture.colorSpace = THREE.SRGBColorSpace;

  const positions = new Float32Array(MAX_PARTICLES * 3);
  const colors = new Float32Array(MAX_PARTICLES * 3);
  positions.fill(-999);
  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  geo.setAttribute("color", new THREE.BufferAttribute(colors, 3));
  const mat = new THREE.PointsMaterial({
    map: sparkTexture, size: 0.32, transparent: true, opacity: 1,
    blending: THREE.AdditiveBlending, depthWrite: false, vertexColors: true,
    sizeAttenuation: true, toneMapped: false,
  });
  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;
  scene.add(points);

  const particles = [];
  for (let i = 0; i < MAX_PARTICLES; i++) {
    particles.push({
      alive: false, life: 0, maxLife: 1, drag: 1, gravity: 0,
      vx: 0, vy: 0, vz: 0, r: 1, g: 1, b: 1, size: 1,
    });
  }
  let cursor = 0;

  const explosionLight = new THREE.PointLight(0xff7a2a, 0, 26, 2);
  scene.add(explosionLight);
  let explosionLightT = 0;

  const activeRings = [];
  const activeSlashes = [];
  const texts = [];
  const textCache = new Map();

  const tmpColor = new THREE.Color();
  const tmpVec = new THREE.Vector3();
  const dummy = new THREE.Object3D();

  function spawnParticle(x, y, z, vx, vy, vz, color, life, size, gravity = -8, drag = 0.9) {
    const p = particles[cursor];
    cursor = (cursor + 1) % MAX_PARTICLES;
    p.alive = true;
    p.life = life;
    p.maxLife = life;
    p.vx = vx; p.vy = vy; p.vz = vz;
    p.gravity = gravity;
    p.drag = drag;
    p.r = color.r; p.g = color.g; p.b = color.b;
    p.size = size;
    const i = particles.indexOf(p);
    positions[i * 3] = x; positions[i * 3 + 1] = y; positions[i * 3 + 2] = z;
    colors[i * 3] = color.r; colors[i * 3 + 1] = color.g; colors[i * 3 + 2] = color.b;
  }

  function burst(pos, colorHex, count = 24, power = 9, life = 0.8, gravity = -10, size = 1) {
    const color = tmpColor.set(colorHex);
    for (let i = 0; i < count; i++) {
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const sp = power * (0.25 + Math.random() * 0.75);
      spawnParticle(
        pos.x, pos.y, pos.z,
        Math.sin(phi) * Math.cos(theta) * sp,
        Math.abs(Math.cos(phi)) * sp * 0.9 + 2,
        Math.sin(phi) * Math.sin(theta) * sp,
        color, life * (0.55 + Math.random() * 0.7),
        size * (0.5 + Math.random()), gravity, 50,
      );
    }
  }

  function trail(pos, colorHex, size = 0.5) {
    const color = tmpColor.set(colorHex);
    spawnParticle(
      pos.x + (Math.random() - 0.5) * 0.12,
      pos.y + (Math.random() - 0.5) * 0.12,
      pos.z + (Math.random() - 0.5) * 0.12,
      (Math.random() - 0.5) * 0.8,
      (Math.random() - 0.5) * 0.5 + 0.5,
      (Math.random() - 0.5) * 0.8,
      color, 0.34 + Math.random() * 0.25, size, 2.2, 10,
    );
  }

  function flash(pos, colorHex = 0xffa04a, size = 5) {
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: sparkTexture, color: colorHex, transparent: true, opacity: 0.95,
      blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
    }));
    sprite.position.copy(pos);
    sprite.scale.setScalar(size);
    scene.add(sprite);
    activeRings.push({ sprite, t: 0, dur: 0.24, from: size * 0.5, to: size * 1.8, fade: true });
  }

  function shockwave(pos, colorHex = 0xffa04a, size = 10) {
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: ringTexture, color: colorHex, transparent: true, opacity: 0.9,
      blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
    }));
    sprite.position.copy(pos);
    sprite.scale.setScalar(1);
    scene.add(sprite);
    activeRings.push({ sprite, t: 0, dur: 0.5, from: 1, to: size, fade: true });
  }

  function explode(pos, colorHex = 0xff7a2a, big = false) {
    burst(pos, 0xffc266, big ? 46 : 26, big ? 16 : 10, big ? 1.2 : 0.8, -9, big ? 1.7 : 1.1);
    burst(pos, colorHex, big ? 30 : 16, big ? 12 : 8, big ? 1 : 0.65, -6, big ? 1.2 : 0.85);
    shockwave(pos, colorHex, big ? 14 : 8);
    flash(pos, 0xffb15a, big ? 9 : 5);
    explosionLight.position.copy(pos);
    explosionLight.position.y += 0.8;
    explosionLight.color.set(colorHex);
    explosionLightT = big ? 0.45 : 0.28;
    explosionLight.intensity = big ? 260 : 120;
  }

  function slash(position, yaw, colorHex, scale = 1) {
    const group = new THREE.Group();
    group.position.copy(position);
    group.position.y += 1.35;
    group.rotation.y = yaw - 0.5;
    const geo = new THREE.TorusGeometry(1.35 * scale, 0.06 * scale, 4, 34, Math.PI * 1.35);
    const mat = new THREE.MeshBasicMaterial({
      color: colorHex, transparent: true, opacity: 0.85,
      blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
    });
    const arc = new THREE.Mesh(geo, mat);
    arc.rotation.x = -Math.PI / 2;
    group.add(arc);
    const mat2 = new THREE.MeshBasicMaterial({
      color: colorHex, transparent: true, opacity: 0.18,
      blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
    });
    const glow = new THREE.Mesh(new THREE.TorusGeometry(1.35 * scale, 0.2 * scale, 4, 34, Math.PI * 1.35), mat2);
    glow.rotation.x = -Math.PI / 2;
    group.add(glow);
    scene.add(group);
    activeSlashes.push({ group, t: 0, dur: 0.34, mats: [mat, mat2], baseYaw: group.rotation.y });
  }

  function makeTextTexture(text, color, fontSize = 76) {
    const key = `${text}|${color}|${fontSize}`;
    if (textCache.has(key)) return textCache.get(key);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    canvas.width = 512; canvas.height = 160;
    ctx.clearRect(0, 0, 512, 160);
    ctx.font = `900 ${fontSize}px Orbitron, Arial Black, sans-serif`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.shadowColor = color;
    ctx.shadowBlur = 24;
    ctx.fillStyle = color;
    ctx.fillText(text, 256, 84);
    ctx.shadowBlur = 0;
    ctx.fillStyle = "rgba(255,255,255,0.92)";
    ctx.font = `900 ${Math.max(20, fontSize * 0.82)}px Orbitron, Arial Black, sans-serif`;
    ctx.globalAlpha = 0.35;
    ctx.fillText(text, 256, 82);
    const tex = new THREE.CanvasTexture(canvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    textCache.set(key, tex);
    return tex;
  }

  function floatingText(pos, text, color = "#7df7ff", scale = 1) {
    const tex = makeTextTexture(text, color);
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: tex, transparent: true, depthWrite: false, depthTest: true, toneMapped: false,
    }));
    sprite.position.copy(pos);
    sprite.position.y += 2.35;
    sprite.scale.set(4.2 * scale, 1.32 * scale, 1);
    scene.add(sprite);
    texts.push({ sprite, t: 0, dur: 1.15, baseY: sprite.position.y });
  }

  function update(dt) {
    // Particles.
    for (let i = 0; i < MAX_PARTICLES; i++) {
      const p = particles[i];
      if (!p.alive) continue;
      p.life -= dt;
      if (p.life <= 0) {
        p.alive = false;
        positions[i * 3 + 1] = -999;
        continue;
      }
      const dragF = Math.exp(-p.drag * dt);
      p.vx *= dragF; p.vz *= dragF;
      p.vy += p.gravity * dt;
      positions[i * 3] += p.vx * dt;
      positions[i * 3 + 1] += p.vy * dt;
      positions[i * 3 + 2] += p.vz * dt;
      const k = Math.min(1, p.life / (p.maxLife * 0.6));
      colors[i * 3] = p.r * k;
      colors[i * 3 + 1] = p.g * k;
      colors[i * 3 + 2] = p.b * k;
    }
    geo.attributes.position.needsUpdate = true;
    geo.attributes.color.needsUpdate = true;

    if (explosionLightT > 0) {
      explosionLightT -= dt;
      explosionLight.intensity *= Math.pow(0.01, dt);
      if (explosionLightT <= 0) explosionLight.intensity = 0;
    }

    for (let i = activeRings.length - 1; i >= 0; i--) {
      const r = activeRings[i];
      r.t += dt;
      const u = Math.min(1, r.t / r.dur);
      const s = r.from + (r.to - r.from) * (1 - Math.pow(1 - u, 3));
      r.sprite.scale.setScalar(s);
      r.sprite.material.opacity = (1 - u) * 0.9;
      if (u >= 1) {
        scene.remove(r.sprite);
        r.sprite.material.dispose();
        activeRings.splice(i, 1);
      }
    }

    for (let i = activeSlashes.length - 1; i >= 0; i--) {
      const s = activeSlashes[i];
      s.t += dt;
      const u = Math.min(1, s.t / s.dur);
      s.group.rotation.y = s.baseYaw + u * 2.1;
      s.group.scale.setScalar(0.9 + u * 0.35);
      s.mats[0].opacity = (1 - u) * 0.95;
      s.mats[1].opacity = (1 - u) * 0.2;
      if (u >= 1) {
        scene.remove(s.group);
        s.group.traverse((o) => {
          if (o.isMesh) { o.geometry.dispose(); o.material.dispose(); }
        });
        activeSlashes.splice(i, 1);
      }
    }

    for (let i = texts.length - 1; i >= 0; i--) {
      const t = texts[i];
      t.t += dt;
      const u = Math.min(1, t.t / t.dur);
      t.sprite.position.y = t.baseY + u * 1.4;
      t.sprite.material.opacity = u < 0.65 ? 1 : 1 - (u - 0.65) / 0.35;
      const pop = u < 0.12 ? 0.65 + u * 3 : 1;
      t.sprite.scale.set(4.2 * pop, 1.32 * pop, 1);
      if (u >= 1) {
        scene.remove(t.sprite);
        t.sprite.material.dispose();
        texts.splice(i, 1);
      }
    }
  }

  function clear() {
    for (const p of particles) { p.alive = false; }
    positions.fill(-999);
    geo.attributes.position.needsUpdate = true;
    for (const r of activeRings) { scene.remove(r.sprite); r.sprite.material.dispose(); }
    activeRings.length = 0;
    for (const s of activeSlashes) {
      scene.remove(s.group);
      s.group.traverse((o) => { if (o.isMesh) { o.geometry.dispose(); o.material.dispose(); } });
    }
    activeSlashes.length = 0;
    for (const t of texts) { scene.remove(t.sprite); t.sprite.material.dispose(); }
    texts.length = 0;
    explosionLight.intensity = 0;
    explosionLightT = 0;
  }

  return {
    points, explode, burst, trail, flash, shockwave, slash, floatingText, update, clear,
    get particleCount() { return particles.filter((p) => p.alive).length; },
  };
}

export function createRocketMesh(owner, glowTexture) {
  const isPlayer = owner === "player";
  const color = isPlayer ? 0x7df7ff : 0xff6a2a;
  const group = new THREE.Group();
  const bodyMat = new THREE.MeshStandardMaterial({
    color: isPlayer ? 0x9ee9f2 : 0x4a302a,
    emissive: color, emissiveIntensity: 2.0, metalness: 0.65, roughness: 0.3,
  });
  const body = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.09, 0.42, 8), bodyMat);
  body.rotation.x = Math.PI / 2;
  group.add(body);
  const tip = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.22, 8), bodyMat);
  tip.rotation.x = Math.PI / 2;
  tip.position.z = 0.3;
  group.add(tip);
  const finMat = new THREE.MeshStandardMaterial({ color: 0x1a171c, metalness: 0.6, roughness: 0.4 });
  for (let i = 0; i < 3; i++) {
    const fin = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.16, 0.18), finMat);
    fin.position.z = -0.16;
    fin.rotation.z = (i / 3) * Math.PI * 2;
    fin.position.x = Math.cos((i / 3) * Math.PI * 2) * 0.12;
    fin.position.y = Math.sin((i / 3) * Math.PI * 2) * 0.12;
    group.add(fin);
  }
  const glowMat = new THREE.SpriteMaterial({
    map: glowTexture, color, transparent: true, opacity: 0.85,
    blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
  });
  const glow = new THREE.Sprite(glowMat);
  glow.scale.setScalar(1.25);
  group.add(glow);
  group.userData.glowMat = glowMat;
  group.userData.bodyMat = bodyMat;
  return group;
}

export function createAudio() {
  let ctx = null;
  let master = null;
  let muted = false;
  let noiseBuffer = null;

  function ensure() {
    if (ctx) return ctx;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    ctx = new AC();
    master = ctx.createGain();
    master.gain.value = 0.55;
    master.connect(ctx.destination);
    const len = Math.floor(ctx.sampleRate * 1.2);
    noiseBuffer = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = noiseBuffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    return ctx;
  }

  function noise(dur, gainValue, type = "lowpass", freq = 900, q = 0.8, sweepTo = null) {
    const c = ensure();
    if (!c || muted) return;
    const src = c.createBufferSource();
    src.buffer = noiseBuffer;
    const filter = c.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, c.currentTime);
    if (sweepTo) filter.frequency.exponentialRampToValueAtTime(Math.max(30, sweepTo), c.currentTime + dur);
    filter.Q.value = q;
    const g = c.createGain();
    g.gain.setValueAtTime(0.0001, c.currentTime);
    g.gain.exponentialRampToValueAtTime(gainValue, c.currentTime + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, c.currentTime + dur);
    src.connect(filter).connect(g).connect(master);
    src.start();
    src.stop(c.currentTime + dur + 0.02);
  }

  function tone(freq, dur, gainValue, type = "sine", slideTo = null, delay = 0) {
    const c = ensure();
    if (!c || muted) return;
    const t0 = c.currentTime + delay;
    const osc = c.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t0 + dur);
    const g = c.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gainValue, t0 + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g).connect(master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.03);
  }

  const sounds = {
    shoot() {
      noise(0.26, 0.5, "bandpass", 1300, 0.6, 220);
      tone(190, 0.28, 0.24, "sawtooth", 46);
      tone(85, 0.3, 0.22, "sine", 38);
    },
    enemyShoot() {
      noise(0.24, 0.32, "bandpass", 700, 0.7, 180);
      tone(120, 0.26, 0.18, "sawtooth", 40);
    },
    explosion() {
      noise(0.65, 0.75, "lowpass", 1400, 0.9, 90);
      tone(66, 0.55, 0.38, "sine", 28);
      tone(150, 0.2, 0.14, "square", 60);
    },
    bigExplosion() {
      noise(1.1, 0.9, "lowpass", 1800, 0.9, 50);
      tone(48, 0.9, 0.5, "sine", 22);
      tone(110, 0.35, 0.2, "sawtooth", 35);
    },
    swing() {
      noise(0.18, 0.2, "bandpass", 500, 1.6, 3200);
    },
    parry() {
      tone(1240, 0.5, 0.22, "triangle", 980);
      tone(1860, 0.42, 0.15, "sine", 1720);
      tone(2620, 0.3, 0.09, "sine", 2500);
      noise(0.16, 0.25, "highpass", 2400, 1.0, 6000);
    },
    reflect() {
      tone(700, 0.25, 0.2, "sawtooth", 2200);
      noise(0.2, 0.2, "bandpass", 1800, 1.1, 4200);
    },
    hit() {
      noise(0.22, 0.42, "lowpass", 700, 1.0, 140);
      tone(100, 0.18, 0.26, "square", 45);
    },
    hurt() {
      noise(0.3, 0.35, "lowpass", 500, 1.0, 100);
      tone(70, 0.32, 0.24, "sawtooth", 35);
    },
    empty() {
      tone(240, 0.06, 0.06, "square", 180);
    },
    count() {
      tone(520, 0.12, 0.12, "square", 500);
    },
    go() {
      tone(780, 0.28, 0.16, "square", 760);
      tone(1170, 0.4, 0.1, "triangle", 1150);
    },
    win() {
      [392, 523, 659, 784].forEach((f, i) => tone(f, 0.9, 0.14, "triangle", f, i * 0.12));
    },
    lose() {
      [330, 262, 196, 147].forEach((f, i) => tone(f, 1.1, 0.14, "sawtooth", f * 0.98, i * 0.17));
    },
    click() {
      tone(420, 0.05, 0.06, "square", 380);
    },
  };

  function play(name) {
    if (muted) return;
    const fn = sounds[name];
    if (fn) fn();
  }

  function unlock() {
    const c = ensure();
    if (c && c.state === "suspended") c.resume();
  }

  function setMuted(v) {
    muted = v;
    if (master) master.gain.value = v ? 0 : 0.55;
  }

  return { play, unlock, setMuted, get muted() { return muted; } };
}

