function spawnParticle(x, y, z, vx, vy, vz, color, life, size, gravity = -8, drag = 0.9) {
  const p = particles[cursor];
  cursor = (cursor + 1) % MAX_PARTICLES;
  p.alive = true;
  p.life = life;
  p.maxLife = life;
  p.vx = vx; p.vy = vy; p.vz = vz;
